function interleave(arr) {
  const mid = Math.ceil(arr.length / 2);
  const first = arr.slice(0, mid);
  const second = arr.slice(mid);
  const result = [];
  for (let i = 0; i < mid; i++) {
    result.push(first[i]);
    if (i < second.length) result.push(second[i]);
  }
  return result;
}
